query_params.query:
SELECT DISTINCT ?film WHERE {
          ?film wdt:P31 wd:Q11424; wdt:P577 ?date; wdt:P57 ?director.
          FILTER(?date >= "1980-01-01T00:00:00Z"^^xsd:dateTime && ?date < "1990-01-01T00:00:00Z"^^xsd:dateTime)
        } LIMIT 800

